/* The cartridge versions this build has: each one's recompiled code and the addresses of
 * the code the runtime hooks into, which moved when the game was translated (generated by
 * tools/recomp.mjs from config/versions.json, config/addresses.json and
 * config/version-addresses.json). The one running is `game`, set when its ROM loads. */
#pragma once
#include <stdint.h>
#include <stddef.h>
#include "recomp_rt.h"

/* The console a cartridge expects: it reads the region from the version register. */
enum { REGION_US, REGION_EU, REGION_JP };

typedef struct GameVersion {
    const char *id, *name, *language, *sha1;
    const char *title;                          /* as sold, for the launcher's case */
    int region;
    const RecompEntry *const *tables;           /* the recompiled code, NULL-terminated */
    uint32_t vblank_send_list;                  /* V blank: about to send the sprite list */
    uint32_t tick_end_wait, tick_waits[8], tick_from[2];                        /* speed statistics */
    uint32_t scroll_column, scroll_row, init_layer, clear_plane_at, redraw_rect;   /* widescreen */
    uint32_t anchor_d1_a4[3], anchor_d2_d3, object_drawn[6];                      /* smooth motion */
    uint32_t driver_update, driver_cmd, driver_cmd_go;                          /* sound driver */
} GameVersion;

/* config/versions.json order: us, eu, fr, de, es, jp. */
#define GAME_VERSION_COUNT 6
extern const GameVersion *const game_versions[GAME_VERSION_COUNT];   /* NULL: not built */
extern const GameVersion *game;                                     /* the one loaded */

const GameVersion *game_version_by_id(const char *id);
/* A file that belongs to one version (its saves, save states, caches): `name` for the USA
 * one, else the name with "-<id>" before its extension ("save.srm" -> "save-fr.srm",
 * "states" -> "states-fr"), so versions never read each other's. */
void game_file_name(char *out, size_t n, const char *name);
/* The cartridge's frame rate and lines per frame: PAL ones run at 50 Hz. */
static inline int game_is_pal(void) { return game && game->region == REGION_EU; }
